class Solution {
public:
    bool isSameTree(TreeNode* p, TreeNode* q) {
        if (!p && !q) return true;
        if (!p || !q) return false;
        return (p->val == q->val) && isSameTree(p->left, q->left) && isSameTree(p->right, q->right);
    }

    bool isSubtree(TreeNode* s, TreeNode* t) {
        if (!s) return false;
        if (isSameTree(s, t)) return true;
        return isSubtree(s->left, t) || isSubtree(s->right, t);
    }
};

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        if (matrix.empty() || matrix[0].empty()) return false;
        int m = matrix.size(), n = matrix[0].size();
        int row = 0, col = n - 1;
        while (row < m && col >= 0) {
            if (matrix[row][col] == target) return true;
            if (matrix[row][col] < target) row++;
            else col--;
        }
        return false;
    }
};

class Solution {
public:
    vector<vector<string>> findLadders(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        vector<vector<string>> result;
        if (!dict.count(endWord)) return result;

        queue<vector<string>> q;
        q.push({beginWord});
        unordered_set<string> visited;
        visited.insert(beginWord);
        bool found = false;

        while (!q.empty() && !found) {
            int levelSize = q.size();
            unordered_set<string> levelVisited;
            for (int i = 0; i < levelSize; ++i) {
                vector<string> path = q.front();
                q.pop();
                string lastWord = path.back();
                for (int j = 0; j < lastWord.size(); ++j) {
                    char originalChar = lastWord[j];
                    for (char c = 'a'; c <= 'z'; ++c) {
                        if (c == originalChar) continue;
                        lastWord[j] = c;
                        if (dict.count(lastWord) && !visited.count(lastWord)) {
                            vector<string> newPath = path;
                            newPath.push_back(lastWord);
                            if (lastWord == endWord) {
                                found = true;
                                result.push_back(newPath);
                            } else {
                                q.push(newPath);
                                levelVisited.insert(lastWord);
                            }
                        }
                    }
                    lastWord[j] = originalChar;
                }
            }
            visited.insert(levelVisited.begin(), levelVisited.end());
        }
        return result;
    }
};

class Solution {
public:
    vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {
        unordered_set<string> wordSet(words.begin(), words.end());
        vector<string> result;

        for (const string& word : words) {
            int n = word.size();
            vector<bool> dp(n + 1, false);
            dp[0] = true;

            for (int i = 1; i <= n; ++i) {
                for (int j = 0; j < i; ++j) {
                    if (dp[j] && wordSet.count(word.substr(j, i - j))) {
                        if (j == 0 && i == n) continue;
                        dp[i] = true;
                        break;
                    }
                }
            }

            if (dp[n]) {
                result.push_back(word);
            }
        }

        return result;
    }
};

