class Solution {
public:
    int minMeetingRooms(vector<vector<int>>& intervals) {
        if (intervals.empty()) return 0;

        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] < b[0];
        });

        priority_queue<int, vector<int>, greater<int>> minHeap;
        minHeap.push(intervals[0][1]);

        for (int i = 1; i < intervals.size(); ++i) {
            if (intervals[i][0] >= minHeap.top()) {
                minHeap.pop();
            }
            minHeap.push(intervals[i][1]);
        }

        return minHeap.size();
    }
};

class Solution {
public:
    vector<string> letterCombinations(string digits) {
        if (digits.empty()) return {};

        vector<string> mapping = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        vector<string> result;
        backtrack(digits, mapping, 0, "", result);
        return result;
    }

private:
    void backtrack(const string& digits, const vector<string>& mapping, int index, string current, vector<string>& result) {
        if (index == digits.size()) {
            result.push_back(current);
            return;
        }

        char digit = digits[index];
        string letters = mapping[digit - '0'];
        for (char c : letters) {
            backtrack(digits, mapping, index + 1, current + c, result);
        }
    }
};

class TicTacToe {
private:
    int n;
    vector<int> rows;
    vector<int> cols;
    int diag1;
    int diag2;

public:
    TicTacToe(int n) {
        this->n = n;
        rows.resize(n, 0);
        cols.resize(n, 0);
        diag1 = 0;
        diag2 = 0;
    }

    int move(int row, int col, int player) {
        int add = (player == 1) ? 1 : -1;
        rows[row] += add;
        cols[col] += add;
        if (row == col) diag1 += add;
        if (row + col == n - 1) diag2 += add;

        if (abs(rows[row]) == n || abs(cols[col]) == n || abs(diag1) == n || abs(diag2) == n) {
            return player;
        }

        return 0;
    }
};

class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> wordSet(wordDict.begin(), wordDict.end());
        int n = s.size();
        vector<bool> dp(n + 1, false);
        dp[0] = true;

        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (dp[j] && wordSet.find(s.substr(j, i - j)) != wordSet.end()) {
                    dp[i] = true;
                    break;
                }
            }
        }

        return dp[n];
    }
};

class MinStack {
private:
    stack<int> st;
    stack<int> minSt;

public:
    MinStack() {

    }

    void push(int val) {
        st.push(val);
        if (minSt.empty() || val <= minSt.top()) {
            minSt.push(val);
        }
    }

    void pop() {
        if (st.top() == minSt.top()) {
            minSt.pop();
        }
        st.pop();
    }

    int top() {
        return st.top();
    }

    int getMin() {
        return minSt.top();
    }
};

